function isoDay(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function defaultRange(grain: BcThGrain): { from: string; to: string } {
  const today = new Date();
  const to = isoDay(today);
  if (grain === 'year') {
    const from = new Date(today.getFullYear() - 2, 0, 1);
    return { from: isoDay(from), to };
  }
  if (grain === 'month') {
    const from = new Date(today.getFullYear(), today.getMonth() - 5, 1);
    return { from: isoDay(from), to };
  }
  const from = new Date(today);
  from.setDate(from.getDate() - 13);
  return { from: isoDay(from), to };
}

function saveBlob(blob: Blob, name: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  a.click();
  URL.revokeObjectURL(url);
}

const LEVELS = [
  { key: 'khu', label: bcThLabel('bcTh.manager.khu') },
  { key: 'vanPhong', label: bcThLabel('bcTh.manager.vanPhong') },
  { key: 'phong', label: bcThLabel('bcTh.manager.phong') },
] as const;

type GridLine = {
  khu: string;
  vp: string;
  phong: string;
  route: string;
  person: string;
  count: number;
  refId: string;
  kind: string;
  khuSpan: number;
  vpSpan: number;
  phongSpan: number;
  showKhu: boolean;
  showVp: boolean;
  showPhong: boolean;
};

function buildLevelGrid(rows: BcThDetail['rows']): GridLine[] {
  const grouped = new Map<string, GridLine>();
  rows.forEach((row) => {
    const khu = row.khuName?.trim() || '';
    const vp = row.vanPhongName?.trim() || '';
    const phong = row.phongName?.trim() || '';
    const route = row.routeName?.trim() || '';
    const person = (row.actorName || (row.kind === 'task' ? row.title : '')).trim();
    const key = [khu, vp, phong, route, person].join('\u001f');
    const hit = grouped.get(key);
    if (hit) {
      hit.count += 1;
      return;
    }
    grouped.set(key, {
      khu, vp, phong, route, person, count: 1,
      refId: row.refId, kind: row.kind,
      khuSpan: 1, vpSpan: 1, phongSpan: 1,
      showKhu: true, showVp: true, showPhong: true,
    });
  });
  const lines = [...grouped.values()].sort((a, b) =>
    a.khu.localeCompare(b.khu, 'vi')
    || a.vp.localeCompare(b.vp, 'vi')
    || a.phong.localeCompare(b.phong, 'vi')
    || a.route.localeCompare(b.route, 'vi')
    || a.person.localeCompare(b.person, 'vi'));
  const span = (index: number, same: (line: GridLine) => boolean, set: (line: GridLine, n: number) => void, hide: (line: GridLine) => void) => {
    let size = 1;
    while (index + size < lines.length && same(lines[index + size])) size += 1;
    set(lines[index], size);
    for (let step = 1; step < size; step += 1) hide(lines[index + step]);
  };
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.showKhu) {
      span(index, (next) => next.khu === line.khu, (row, n) => { row.khuSpan = n; }, (row) => { row.showKhu = false; });
    }
    if (line.showVp) {
      span(
        index,
        (next) => next.khu === line.khu && next.vp === line.vp,
        (row, n) => { row.vpSpan = n; },
        (row) => { row.showVp = false; },
      );
    }
    if (line.showPhong) {
      span(
        index,
        (next) => next.khu === line.khu && next.vp === line.vp && next.phong === line.phong,
        (row, n) => { row.phongSpan = n; },
        (row) => { row.showPhong = false; },
      );
    }
  }
  return lines;
}

function activityLine(column: { checkInCount: number; userCount: number }): string {
  return `${column.checkInCount} ${bcThLabel('bcTh.manager.sessions')} · ${column.userCount} ${bcThLabel('bcTh.manager.people')}`;
}

const ManagerDetail: React.FC<{
  detail: BcThDetail;
  openLevel: string;
  group: string;
  onOpenLevel: (level: string) => void;
  onGroup: (group: string) => void;
  onOpen: (refId: string) => void;
}> = ({ detail, openLevel, group, onOpenLevel, onGroup, onOpen }) => {
  const levels = detail.levels ?? EMPTY_BC_TH_DETAIL.levels;
  const columns = LEVELS.map((level) => ({
    ...level,
    cell: levels[level.key] ?? EMPTY_BC_TH_DETAIL.levels.khu,
  }));
  const open = columns.find((col) => col.key === openLevel);
  const cards = open?.cell.groups ?? [];
  const showLevels = columns.some((col) => col.cell.groupCount > 0 || col.cell.groups.length > 0);

  return (
    <>
      {showLevels ? (
        <div className={styles.levels} data-testid={`${TEST_ID}-levels`}>
          {columns.map((col) => (
            <button
              key={col.key}
              type="button"
              className={openLevel === col.key ? `${styles.level} ${styles.levelOn}` : styles.level}
              aria-expanded={openLevel === col.key}
              onClick={() => onOpenLevel(openLevel === col.key ? '' : col.key)}
            >
              <span className={styles.levelLabel}>{col.label}</span>
              <span className={styles.levelCount}>{col.cell.groupCount}</span>
            </button>
          ))}
          <div className={styles.levelFoot}>{activityLine(columns[0].cell)}</div>
          {open ? (
            <div className={styles.nameList}>
              {cards.length === 0 ? (
                <p className={styles.empty}>{bcThLabel('bcTh.manager.empty')}</p>
              ) : (
                cards.map((card, index) => (
                  <ManagerName
                    key={card.key}
                    card={card}
                    previous={index > 0 ? cards[index - 1] : null}
                    pressed={group === card.key}
                    onClick={() => onGroup(group === card.key ? '' : card.key)}
                  />
                ))
              )}
            </div>
          ) : null}
          {openLevel || group ? (
            <div className={styles.levelActions}>
              {group ? (
                <button type="button" className={styles.textBtn} onClick={() => onGroup('')}>
                  {bcThLabel('bcTh.manager.clear')}
                </button>
              ) : null}
              {openLevel ? (
                <button type="button" className={styles.textBtn} onClick={() => onOpenLevel('')}>
                  {bcThLabel('bcTh.manager.collapse')}
                </button>
              ) : null}
            </div>
          ) : null}
        </div>
      ) : null}
      {detail.rows.length === 0 ? (
        <p className={styles.empty}>Không có dòng cho chỉ số này.</p>
      ) : (
        <div className={styles.gridWrap}>
          <table className={styles.grid}>
            <thead>
              <tr>
                <th>{bcThLabel('bcTh.manager.khu')}</th>
                <th>{bcThLabel('bcTh.manager.vanPhong')}</th>
                <th>{bcThLabel('bcTh.manager.phong')}</th>
                <th>{bcThLabel('bcTh.manager.route')}</th>
                <th>{bcThLabel('bcTh.manager.staff')}</th>
                <th>{bcThLabel('bcTh.manager.sessionsCol')}</th>
              </tr>
            </thead>
            <tbody>
              {buildLevelGrid(detail.rows).map((line) => (
                <tr
                  key={`${line.khu}-${line.vp}-${line.phong}-${line.route}-${line.person}-${line.refId}`}
                  data-testid={`${TEST_ID}-detail-row-${line.refId}`}
                  onClick={() => {
                    if (line.kind === 'session' && line.refId) onOpen(line.refId);
                  }}
                >
                  {line.showKhu ? <td rowSpan={line.khuSpan}>{line.khu || '—'}</td> : null}
                  {line.showVp ? <td rowSpan={line.vpSpan}>{line.vp || '—'}</td> : null}
                  {line.showPhong ? <td rowSpan={line.phongSpan}>{line.phong || '—'}</td> : null}
                  <td>{line.route || '—'}</td>
                  <td>{line.person || '—'}</td>
                  <td>{line.count}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
};

const ManagerName: React.FC<{
  card: BcThManagerCard;
  previous: BcThManagerCard | null;
  pressed: boolean;
  onClick: () => void;
}> = ({ card, previous, pressed, onClick }) => {
  const master = card.masterName.trim();
  const parent = card.parentName.trim();
  const showMaster = master.length > 0 && card.masterKey !== (previous?.masterKey ?? '');
  const showParent = parent.length > 0 && (showMaster || card.parentKey !== (previous?.parentKey ?? ''));
  return (
    <>
      {showMaster ? <div className={styles.masterHead}>{master}</div> : null}
      {showParent ? <div className={styles.parentHead}>{parent}</div> : null}
      <button
        type="button"
        className={pressed ? `${styles.nameBtn} ${styles.nameBtnOn}` : styles.nameBtn}
        aria-pressed={pressed}
        onClick={onClick}
      >
        <span>{card.name}</span>
        <span className={styles.groupMeta}>{activityLine(card)}</span>
      </button>
    </>
  );
};

const BcThPage: React.FC = () => {
  const dispatch = useDispatch();
  const navigate = useInAppNavigate();
  const initial = defaultRange('day');
  const [grain, setGrain] = useState<BcThGrain>('day');
  const [from, setFrom] = useState(initial.from);
  const [to, setTo] = useState(initial.to);
  const [route, setRoute] = useState('');
  const [zoneOrgCode, setZoneOrgCode] = useState('');
  const [viewed, setViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [summary, setSummary] = useState<BcThSummary | null>(null);
  const [pick, setPick] = useState<{ indicator: string; bucket?: string } | null>(null);
  const [group, setGroup] = useState('');
  const [openLevel, setOpenLevel] = useState('');
  const [detail, setDetail] = useState<BcThDetail>(EMPTY_BC_TH_DETAIL);
  const [detailLoading, setDetailLoading] = useState(false);

  const query = useMemo<BcThQuery>(
    () => ({
      grain,
      from,
      to,
      route: route.trim() || undefined,
      zoneOrgCode: zoneOrgCode.trim() || undefined,
    }),
    [grain, from, to, route, zoneOrgCode],
  );

  const load = useCallback(async () => {
    setLoading(true);
    setPick(null);
    setGroup('');
    setOpenLevel('');
    setDetail(EMPTY_BC_TH_DETAIL);
    try {
      const data = await bcThEndpoint.summary(query);
      setSummary(data);
      setViewed(true);
      if (data.tasksUnavailable) {
        dispatchAppToast(dispatch, {
          message: 'TaskService chưa trả series — phần tuần vẫn hiển thị',
          type: 'warning',
        });
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Không tải được báo cáo';
      dispatchAppToast(dispatch, { message, type: 'error' });
    } finally {
      setLoading(false);
    }
  }, [dispatch, query]);

  useEffect(() => {
    if (!viewed || !pick || !summary) return;
    const timer = setTimeout(() => {
      setDetailLoading(true);
      bcThEndpoint
        .detail(query, pick.indicator, pick.bucket, group)
        .then((data) => setDetail(data))
        .catch((err: unknown) => {
          const message = err instanceof Error ? err.message : 'Không tải được chi tiết';
          dispatchAppToast(dispatch, { message, type: 'error' });
          setDetail(EMPTY_BC_TH_DETAIL);
        })
        .finally(() => setDetailLoading(false));
    }, 0);
    return () => clearTimeout(timer);
  }, [viewed, pick, summary, query, group, dispatch]);

  const onGrain = (next: BcThGrain) => {
    const range = defaultRange(next);
    setGrain(next);
    setFrom(range.from);
    setTo(range.to);
    setViewed(false);
    setSummary(null);
    setPick(null);
    setGroup('');
    setOpenLevel('');
  };

  const chooseIndicator = (indicator: string, bucket?: string) => {
    setPick({ indicator, bucket });
    setGroup('');
    setOpenLevel('');
  };

  const exportAs = async (format: 'csv' | 'pdf' | 'docx') => {
    if (!viewed) return;
    try {
      const blob = await bcThEndpoint.exportFile(query, format);
      saveBlob(blob, `bc-th.${format}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Không xuất được file';
      dispatchAppToast(dispatch, { message, type: 'error' });
    }
  };

  const toolbar = (
    <LinListToolbar
      testIdPrefix={TEST_ID}
      profile="generic"
      actions={[
        {
          id: 'refresh',
          placement: 'left',
          testId: `${TEST_ID}-refresh`,
          render: () => (
            <Button
              variant="secondary"
              size="sm"
              data-testid={`${TEST_ID}-refresh`}
              onClick={() => void load()}
            >
              {getErpListToolbarActionLabel('refresh')}
            </Button>
          ),
        },
        {
          id: 'pdf',
          placement: 'right',
          testId: `${TEST_ID}-export-pdf`,
          render: () => (
            <Button
              variant="secondary"
              size="sm"
              data-testid={`${TEST_ID}-export-pdf`}
              disabled={!viewed}
              onClick={() => void exportAs('pdf')}
            >
              PDF
            </Button>
          ),
        },
        {
          id: 'docx',
          placement: 'right',
          testId: `${TEST_ID}-export-docx`,
          render: () => (
            <Button
              variant="secondary"
              size="sm"
              data-testid={`${TEST_ID}-export-docx`}
              disabled={!viewed}
              onClick={() => void exportAs('docx')}
            >
              Word
            </Button>
          ),
        },
        {
          id: 'csv',
          placement: 'right',
          testId: `${TEST_ID}-export-csv`,
          render: () => (
            <Button
              variant="secondary"
              size="sm"
              data-testid={`${TEST_ID}-export-csv`}
              disabled={!viewed}
              onClick={() => void exportAs('csv')}
            >
              CSV
            </Button>
          ),
        },
      ]}
    />
  );

  const clearView = () => {
    setViewed(false);
    setSummary(null);
    setPick(null);
  };

  const listFilters = (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID}
      fromDate={from}
      toDate={to}
      dateLabel="Thời gian"
      onDateChange={(nextFrom, nextTo) => {
        setFrom(nextFrom ?? '');
        setTo(nextTo ?? '');
        clearView();
      }}
      onSearch={() => void load()}
      searchAriaLabel={getErpListToolbarActionLabel('view')}
      loading={loading}
      dateLeading={(
        <div data-testid={`${TEST_ID}-field-grain`}>
          <Select
            label="Kỳ"
            options={GRAIN_OPTIONS}
            value={grain}
            onChange={(e) => onGrain(String(e.target.value) as BcThGrain)}
            data-testid={`${TEST_ID}-grain`}
            fullWidth
            size="small"
          />
        </div>
      )}
      leading={(
        <>
          <div data-testid={`${TEST_ID}-field-route`}>
            <Input
              label="Tuyến"
              value={route}
              onChange={(e) => setRoute(e.target.value)}
              data-testid={`${TEST_ID}-route`}
            />
          </div>
          <div data-testid={`${TEST_ID}-field-zone`}>
            <Input
              label="Mã khu"
              value={zoneOrgCode}
              onChange={(e) => setZoneOrgCode(e.target.value)}
              data-testid={`${TEST_ID}-zone`}
            />
          </div>
        </>
      )}
    />
  );

  const legend = (series: { code: string; label: string }[]) => (
    <div className={styles.legend}>
      {series.map((item, index) => (
        <span key={item.code}>
          <i
            className={styles.swatch}
            style={{ background: BC_TH_COLORS[index % BC_TH_COLORS.length] }}
          />
          {summary?.cards.find((c) => c.indicatorCode === item.code)?.label || item.label}
        </span>
      ))}
    </div>
  );

  return (
    <div
      className={styles.page}
      data-catalog-list-page
      data-lin-list-layout="erp-filter-bar"
      data-testid={`${TEST_ID}-page`}
      data-required-permission="patrol.bc-th.read"
    >
      <LinPageLayout
        kind="report"
        listLayoutVariant="erp-filter-bar"
        listHeaderClassName={LIN_ERP_LIST_FILTER_LAYOUT.header}
        listFiltersClassName={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        header={{
          title: 'Báo cáo tổng hợp',
          titleIconClass: 'fas fa-chart-column',
          pageId: PAGE_ID,
        }}
        toolbar={toolbar}
        listTitle="Kết quả"
        filters={listFilters}
        filtersTestId={`${TEST_ID}-filters`}
        showTableLoading={false}
        pageLoading={loading}
        skeletonRows={0}
      >
        {!viewed || !summary ? (
          <p className={styles.empty} data-testid={`${TEST_ID}-hint`}>
            Nhấn Xem để tải số liệu.
          </p>
        ) : (
          <>
            <section className={styles.cards} aria-label="Chỉ số">
              {summary.cards.map((card) => (
                <button
                  key={card.indicatorCode}
                  type="button"
                  className={`${styles.card}${
                    pick?.indicator === card.indicatorCode && !pick.bucket ? ` ${styles.cardOn}` : ''
                  }`}
                  data-testid={`${TEST_ID}-card-${card.indicatorCode}`}
                  onClick={() => chooseIndicator(card.indicatorCode)}
                >
                  <span className={styles.cardLabel}>{card.label}</span>
                  <span className={styles.cardValue}>{card.value.toLocaleString('vi-VN')}</span>
                </button>
              ))}
            </section>
            <section className={styles.chartCard}>
              <h2>Tuần đường / tuần kiểm</h2>
              {legend(SESSION_SERIES)}
              <div className={styles.chartScroll}>
                <BcThChart
                  testIdPrefix={`${TEST_ID}-patrol`}
                  points={summary.points}
                  series={SESSION_SERIES.map((item) => ({
                    ...item,
                    label: summary.cards.find((c) => c.indicatorCode === item.code)?.label || item.label,
                  }))}
                  onPick={chooseIndicator}
                />
              </div>
            </section>
            <section className={styles.chartCard}>
              <h2>Trạng thái task</h2>
              {legend(TASK_SERIES)}
              <div className={styles.chartScroll}>
                <BcThChart
                  testIdPrefix={`${TEST_ID}-task`}
                  points={summary.points}
                  series={TASK_SERIES.map((item) => ({
                    ...item,
                    label: summary.cards.find((c) => c.indicatorCode === item.code)?.label || item.label,
                  }))}
                  onPick={chooseIndicator}
                />
              </div>
            </section>
            <section className={styles.detail} data-testid={`${TEST_ID}-detail`}>
              {!pick ? (
                <p className={styles.empty}>Chọn một thẻ hoặc một cột để xem dòng.</p>
              ) : detailLoading ? (
                <p className={styles.empty}>Đang tải chi tiết…</p>
              ) : (
                <ManagerDetail
                  detail={detail}
                  openLevel={openLevel}
                  group={group}
                  onOpenLevel={setOpenLevel}
                  onGroup={setGroup}
                  onOpen={(refId) => navigate(`/td-tk/${encodeURIComponent(refId)}`)}
                />
              )}
            </section>
          </>
        )}
      </LinPageLayout>
    </div>
  );
};

export default BcThPage;
