import React from 'react';
import type { BcThPoint } from '../../services/patrol/bcThEndpoint';

export const BC_TH_COLORS = ['#1677ff', '#52c41a', '#fa8c16', '#722ed1', '#eb2f96', '#13c2c2'];

type Series = { code: string; label: string };

type Props = {
  testIdPrefix: string;
  points: BcThPoint[];
  series: Series[];
  onPick: (code: string, bucket: string) => void;
};

export const BcThChart: React.FC<Props> = ({ testIdPrefix, points, series, onPick }) => {
  const buckets = Array.from(new Set(points.map((p) => p.bucketStart.slice(0, 10)))).sort();
  const max = Math.max(1, ...points.map((p) => p.value));
  const slot = 22;
  const groupWidth = series.length * slot + 8;
  const width = Math.max(320, buckets.length * groupWidth + 16);
  const height = 176;

  return (
    <div data-testid={`${testIdPrefix}-chart`}>
      <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height} role="img">
        {buckets.map((bucket, index) => (
          <g key={bucket} transform={`translate(${8 + index * groupWidth}, 0)`}>
            {series.map((item, seriesIndex) => {
              const value = points.find(
                (p) => p.indicatorCode === item.code && p.bucketStart.slice(0, 10) === bucket,
              )?.value ?? 0;
              const barHeight = (value / max) * 112;
              const y = 136 - barHeight;
              return (
                <g key={item.code}>
                  {value > 0 ? (
                    <text
                      x={seriesIndex * slot + 6}
                      y={Math.max(10, y - 2)}
                      textAnchor="middle"
                      fontSize={9}
                      fill="#262626"
                    >
                      {value}
                    </text>
                  ) : null}
                  <rect
                    x={seriesIndex * slot}
                    y={y}
                    width={12}
                    height={Math.max(barHeight, value > 0 ? 2 : 0)}
                    fill={BC_TH_COLORS[seriesIndex % BC_TH_COLORS.length]}
                    data-testid={`${testIdPrefix}-bar-${item.code}-${bucket}`}
                    onClick={() => onPick(item.code, bucket)}
                  >
                    <title>{`${item.label} ${bucket}: ${value}`}</title>
                  </rect>
                </g>
              );
            })}
            <text x={0} y={164} fontSize={9} fill="#595959">
              {bucket.slice(5)}
            </text>
          </g>
        ))}
      </svg>
    </div>
  );
};
