import { apiClient, unwrap } from '../api';
import type { BffResponse } from '../api';

const BASE = '/patrol/bc-th';

export type BcThGrain = 'day' | 'month' | 'year';

export type BcThQuery = {
  grain: BcThGrain;
  from: string;
  to: string;
  route?: string;
  zoneOrgCode?: string;
};

export type BcThCard = {
  indicatorCode: string;
  label: string;
  value: number;
};

export type BcThPoint = {
  indicatorCode: string;
  bucketStart: string;
  value: number;
};

export type BcThSummary = {
  grain: BcThGrain;
  from: string;
  to: string;
  tasksUnavailable: boolean;
  cards: BcThCard[];
  points: BcThPoint[];
};

export type BcThDetailRow = {
  kind: string;
  indicatorCode: string;
  bucketStart?: string | null;
  refId: string;
  code: string;
  title: string;
  actor: string;
  actorName: string;
  route: string;
  routeName: string;
  khuName: string;
  vanPhongName: string;
  phongName: string;
  status: string;
  dueAt?: string | null;
};

export type BcThManagerCard = {
  key: string;
  name: string;
  parentKey: string;
  parentName: string;
  masterKey: string;
  masterName: string;
  checkInCount: number;
  userCount: number;
};

export type BcThManagerColumn = {
  groupCount: number;
  checkInCount: number;
  userCount: number;
  groups: BcThManagerCard[];
};

export type BcThDetail = {
  levels: {
    khu: BcThManagerColumn;
    vanPhong: BcThManagerColumn;
    phong: BcThManagerColumn;
  };
  rows: BcThDetailRow[];
};

const EMPTY_COLUMN: BcThManagerColumn = {
  groupCount: 0,
  checkInCount: 0,
  userCount: 0,
  groups: [],
};

export const EMPTY_BC_TH_DETAIL: BcThDetail = {
  levels: { khu: EMPTY_COLUMN, vanPhong: EMPTY_COLUMN, phong: EMPTY_COLUMN },
  rows: [],
};

function qs(query: BcThQuery, extra?: Record<string, string>): string {
  const params = new URLSearchParams();
  params.set('grain', query.grain);
  params.set('from', query.from);
  params.set('to', query.to);
  if (query.route) params.set('route', query.route);
  if (query.zoneOrgCode) params.set('zoneOrgCode', query.zoneOrgCode);
  if (extra) {
    Object.entries(extra).forEach(([key, value]) => {
      if (value) params.set(key, value);
    });
  }
  return params.toString();
}

export const bcThEndpoint = {
  summary: async (query: BcThQuery) => {
    const res = await apiClient.get<BffResponse<BcThSummary>>(`${BASE}/summary?${qs(query)}`);
    return unwrap(res);
  },

  detail: async (query: BcThQuery, indicator: string, bucket?: string, group?: string) => {
    const res = await apiClient.get<BffResponse<BcThDetail>>(
      `${BASE}/detail?${qs(query, { indicator, bucket: bucket ?? '', group: group ?? '' })}`,
    );
    return unwrap(res) ?? EMPTY_BC_TH_DETAIL;
  },

  exportFile: (query: BcThQuery, format: 'csv' | 'pdf' | 'docx') =>
    apiClient.getBlob(`${BASE}/export?${qs(query, { format })}`),
};
